import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.Dsf4_p3t.js";const u=JSON.parse('{"title":"输入与事件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/input.md","filePath":"zh/guide/input.md","lastUpdated":1786978364000}'),i={name:"zh/guide/input.md"};function r(l,t,c,n,h,s){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="输入与事件" tabindex="-1">输入与事件 <a class="header-anchor" href="#输入与事件" aria-label="Permalink to &quot;输入与事件&quot;">​</a></h1><p>鼠标/触摸事件从平台桥接流经 Widget 树。</p><h2 id="事件流" tabindex="-1">事件流 <a class="header-anchor" href="#事件流" aria-label="Permalink to &quot;事件流&quot;">​</a></h2><ol><li><code>GlfwBridge</code> 接收 GLFW 鼠标事件（按钮、移动、滚轮）并通过回调转发</li><li><code>Application</code> 执行递归 <code>HitTest()</code> 找到光标下最深层的 Widget</li><li>调用命中 Widget 的事件处理函数，传入局部坐标</li></ol><h2 id="事件类型" tabindex="-1">事件类型 <a class="header-anchor" href="#事件类型" aria-label="Permalink to &quot;事件类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事件</th><th>说明</th></tr></thead><tbody><tr><td><code>OnPointerDown(pos)</code></td><td>指针按下</td></tr><tr><td><code>OnPointerUp(pos)</code></td><td>指针释放</td></tr><tr><td><code>OnPointerMove(pos)</code></td><td>指针移动（悬停或拖拽）</td></tr><tr><td><code>OnPointerEnter()</code></td><td>指针进入组件区域</td></tr><tr><td><code>OnPointerExit()</code></td><td>指针离开组件区域</td></tr></tbody></table><h2 id="命中测试缓存" tabindex="-1">命中测试缓存 <a class="header-anchor" href="#命中测试缓存" aria-label="Permalink to &quot;命中测试缓存&quot;">​</a></h2><p>指针移动事件频率高，使用命中测试缓存避免每次都遍历整棵树。布局变化时缓存自动失效。</p><h2 id="拖拽" tabindex="-1">拖拽 <a class="header-anchor" href="#拖拽" aria-label="Permalink to &quot;拖拽&quot;">​</a></h2><p><code>Draggable</code> 组件重写 <code>OnPointerMove</code> 更新拖拽偏移。<code>ScrollView</code> 支持拖拽滚动。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>拖拽进行中（<code>OnPointerDown</code> 后的移动事件），移动事件会直接发给被按下的 Widget，跳过命中测试。这确保 <code>Draggable</code> 在指针移出其布局边界时（因绘制时平移）仍能持续接收事件。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./widgets">Widget 系统</a></li><li><a href="./routing">路由导航</a></li></ul>',13)])])}const b=e(i,[["render",r]]);export{u as __pageData,b as default};
